// Generated by `just generate` from `src/plugins/claudetto/slices/patch/lab/write.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `tool.call` hook on `Edit` and `Write` of the `patch` slice (design D64).
// The stub of `process.run` stands for `git`, and records each run, so no command runs.
// A subagent in a linked worktree gets a patch in the main checkout, and the main thread and a main checkout get nothing.

import type { On } from "claude-code";
import { type Engine, expect, test } from "claude-code/testing";

const OK = {
  exitCode: 0,
  stdout: "",
  stderr: "",
  isStdoutTruncated: false,
  isStderrTruncated: false,
};

/** The answer of `rev-parse`: the top, the git dir, the common dir, and `HEAD`. The git dir differs from the common dir in a linked worktree. */
const WORKTREE = [
  "/main/.claude/worktrees/w1",
  "/main/.git/worktrees/w1",
  "/main/.git",
  "abc123",
].join("\n");
const MAIN = ["/main", "/main/.git", "/main/.git", "abc123"].join("\n");

/** Stubs the tool, the file system, and `git`. `rev` is the answer of `rev-parse`. */
const stub = (on: On, rev: string, files: Record<string, string> = {}) => {
  const runs: { argv: readonly string[]; cwd?: string; env?: object }[] = [];
  const writes: Record<string, string> = {};
  on("tool.call", () => ({ result: "ok" }));
  on("fs.exists", (_$, e) => ({ value: e.path in files }));
  on("fs.read", (_$, e) => ({ value: files[e.path] ?? "" }));
  on("fs.write", (_$, e) => {
    writes[e.path] = e.text;
    return { value: undefined };
  });
  on("process.run", (_$, e) => {
    runs.push({ argv: e.argv, cwd: e.init?.cwd, env: e.init?.env });
    return { value: { ...OK, stdout: e.argv[1] === "rev-parse" ? rev : "" } };
  });
  return { runs, writes };
};

const edit = ($: Engine, agentId?: string) =>
  $.tool.call({
    tool: "Edit",
    file_path: "/main/.claude/worktrees/w1/a.ts",
    old_string: "a",
    new_string: "b",
    ...(agentId ? { agentId } : {}),
  });

// biome-ignore lint/plugin: a test name that a `slice.ts` file references
test("an `Edit` of a subagent in a worktree writes the base and the cumulative patch in the main checkout", async ($: Engine, on: On) => {
  const seen = stub(on, WORKTREE);
  await edit($, "agent1");
  expect(seen.writes["/main/.claudetto/patches/agent1/base"]).toBe("abc123");
  const diff = seen.runs.find((r) => r.argv.includes("diff"));
  expect(diff?.argv).toContain("--binary");
  expect(diff?.argv).toContain(
    "--output=/main/.claudetto/patches/agent1/changes.patch",
  );
  expect(diff?.argv).toContain("abc123");
  expect(diff?.cwd).toBe("/main/.claude/worktrees/w1");
  // The temporary index leaves the index of the worktree alone, and holds the untracked files.
  expect(JSON.stringify(diff?.env)).toContain("claudetto.index");
  expect(seen.runs.some((r) => r.argv.join(" ") === "git add -A")).toBe(true);
});

test("a later patch keeps the base of the first write", async ($: Engine, on: On) => {
  const seen = stub(on, WORKTREE.replace("abc123", "def456"), {
    "/main/.claudetto/patches/agent1/base": "abc123\n",
  });
  await edit($, "agent1");
  expect(seen.writes["/main/.claudetto/patches/agent1/base"]).toBeUndefined();
  const diff = seen.runs.find((r) => r.argv.includes("diff"));
  expect(diff?.argv).toContain("abc123");
});

test("an `Edit` of the main thread writes no patch", async ($: Engine, on: On) => {
  const seen = stub(on, WORKTREE);
  await edit($);
  expect(seen.runs).toEqual([]);
  expect(seen.writes).toEqual({});
});

test("an `Edit` of a subagent in the main checkout writes no patch", async ($: Engine, on: On) => {
  const seen = stub(on, MAIN);
  await edit($, "agent1");
  expect(seen.writes).toEqual({});
  expect(seen.runs.some((r) => r.argv.includes("diff"))).toBe(false);
});
